-- Queue and delay: parallel stations, configurable capacity, existing NAXA-family operational audit.
begin;
alter table public.zp_orders add column priority int not null default 0 check(priority between 0 and 2),add column called_at timestamptz,add column eta_saturated boolean not null default false;
create table public.zp_station_capacity(org_id uuid not null,site_id uuid not null,post text not null check(post in ('kitchen','bar','snack')),parallel_slots int not null check(parallel_slots between 1 and 100),member_id uuid not null,updated_at timestamptz not null default now(),primary key(site_id,post),foreign key(site_id,org_id) references public.zp_site_modes(site_id,org_id),foreign key(member_id,org_id) references public.zp_members(id,org_id));
create table public.zp_station_capacity_events(id uuid primary key default gen_random_uuid(),org_id uuid not null,site_id uuid not null,post text not null,parallel_slots int not null,member_id uuid not null,created_at timestamptz not null default now(),foreign key(site_id,org_id) references public.zp_site_modes(site_id,org_id),foreign key(member_id,org_id) references public.zp_members(id,org_id));
create function public.zp_capacity_set(p_access text,p_site uuid,p_post text,p_slots int) returns boolean language plpgsql security invoker set search_path=pg_catalog,public as $$
declare m public.zp_members;begin m:=public.zp_erp_actor(p_access,p_site);
 perform 1 from public.zp_site_modes where site_id=p_site for update;
 if not exists(select 1 from public.zp_site_modes s where s.site_id=p_site and ((s.space='restaurant' and (p_post='kitchen' or (p_post='bar' and s.bar_enabled))) or (s.space='snack_bar' and p_post='snack'))) then raise exception 'POST_DENIED';end if;
 insert into public.zp_station_capacity values(m.org_id,p_site,p_post,p_slots,m.id,now()) on conflict(site_id,post) do update set parallel_slots=excluded.parallel_slots,member_id=excluded.member_id,updated_at=excluded.updated_at;
 insert into public.zp_station_capacity_events(org_id,site_id,post,parallel_slots,member_id) values(m.org_id,p_site,p_post,p_slots,m.id);return true;end $$;
create function public.zp_capacity_snapshot(p_access text,p_site uuid) returns jsonb language plpgsql stable security invoker set search_path=pg_catalog,public as $$
declare m public.zp_members;begin m:=public.zp_erp_actor(p_access,p_site);return coalesce((select jsonb_agg(jsonb_build_object('post',post,'parallel_slots',parallel_slots)) from public.zp_station_capacity where org_id=m.org_id and site_id=p_site),'[]'::jsonb);end $$;
create or replace function public.zp_order_initial_eta() returns trigger language plpgsql security invoker set search_path=pg_catalog,public as $$
declare mins numeric;begin
 if new.initial_promised_at is null and new.total_xaf>0 then
 select greatest(1,coalesce(max(ceil((w.minutes+coalesce((select sum(i.prep_minutes::numeric*l.qty) from public.zp_order_lines l join public.zp_menu_items i on i.id=l.item_id join public.zp_orders o on o.id=l.order_id where l.org_id=new.org_id and l.site_id=new.site_id and l.order_id<>new.id and l.post=w.post and l.state in ('received','preparing') and o.status not in ('served','cancelled')),0))/coalesce((select parallel_slots from public.zp_station_capacity where site_id=new.site_id and post=w.post),1))),15)) into mins
 from (select l.post,sum(i.prep_minutes::numeric*l.qty) minutes from public.zp_order_lines l join public.zp_menu_items i on i.id=l.item_id where l.order_id=new.id group by l.post) w;
 new.eta_saturated:=mins>1440;new.initial_promised_at:=clock_timestamp()+make_interval(mins=>least(1440,mins)::int);new.promised_at:=new.initial_promised_at;
 end if;return new;end $$;
create function public.zp_delay_explain(p_access text,p_site uuid,p_order uuid,p_minutes int,p_reason text) returns timestamptz language plpgsql security invoker set search_path=pg_catalog,public as $$
declare m public.zp_members;o public.zp_orders;d timestamptz;begin m:=public.zp_erp_actor(p_access,p_site);
 if p_minutes is null or p_minutes not between 1 and 240 or length(trim(coalesce(p_reason,''))) not between 5 and 500 then raise exception 'INVALID_DELAY';end if;
 select * into o from public.zp_orders where id=p_order and org_id=m.org_id and site_id=p_site and status in ('received','preparing','ready') and guest_served_at is null for update;
 if o.id is null then raise exception 'DENIED';end if;
 d:=clock_timestamp()+make_interval(mins=>p_minutes);
 update public.zp_orders set promised_at=d,initial_promised_at=coalesce(initial_promised_at,d),eta_saturated=false where id=o.id;
 insert into public.zp_order_events(order_id,org_id,site_id,member_id,event_type,payload) values(o.id,m.org_id,p_site,m.id,'delay_explained',jsonb_build_object('previous',o.promised_at,'initial',o.initial_promised_at,'promised_at',d,'minutes',p_minutes,'reason',trim(p_reason)));return d;end $$;
create function public.zp_order_priority(p_access text,p_site uuid,p_order uuid,p_priority int,p_reason text) returns boolean language plpgsql security invoker set search_path=pg_catalog,public as $$
declare m public.zp_members;o public.zp_orders;begin m:=public.zp_erp_actor(p_access,p_site);
 if p_priority is null or p_priority not between 0 and 2 or length(trim(coalesce(p_reason,''))) not between 5 and 500 then raise exception 'INVALID_PRIORITY';end if;
 select * into o from public.zp_orders where id=p_order and org_id=m.org_id and site_id=p_site and status in ('received','preparing','ready') for update;if o.id is null then raise exception 'DENIED';end if;
 update public.zp_orders set priority=p_priority where id=o.id;
 insert into public.zp_order_events(order_id,org_id,site_id,member_id,event_type,payload) values(o.id,m.org_id,p_site,m.id,'priority',jsonb_build_object('before',o.priority,'after',p_priority,'reason',trim(p_reason)));return true;end $$;
create function public.zp_call_number(p_access text,p_site uuid,p_order uuid) returns timestamptz language plpgsql security invoker set search_path=pg_catalog,public as $$
declare m public.zp_members;o public.zp_orders;ts timestamptz;begin m:=public.zp_erp_actor(p_access,p_site);
 select * into o from public.zp_orders where id=p_order and org_id=m.org_id and site_id=p_site and channel in ('counter','takeaway') and status='ready' for update;if o.id is null then raise exception 'DENIED';end if;
 if o.called_at is not null then return o.called_at;end if;
 update public.zp_orders set called_at=clock_timestamp() where id=o.id returning called_at into ts;
 insert into public.zp_order_events(order_id,org_id,site_id,member_id,event_type,payload) values(o.id,m.org_id,p_site,m.id,'number_called',jsonb_build_object('number',o.service_number));return ts;end $$;
create or replace function public.zp_business_snapshot(p_access text,p_site uuid) returns jsonb language plpgsql stable security invoker set search_path=pg_catalog,public as $$
declare m public.zp_members;mode jsonb;items jsonb;orders jsonb;tables jsonb;begin m:=public.zp_business_actor(p_access,p_site);if m.role_code not in ('promoteur','manager') then raise exception 'DENIED';end if;
 select to_jsonb(s) into mode from public.zp_site_modes s where s.site_id=p_site and s.org_id=m.org_id;
 select coalesce(jsonb_agg(to_jsonb(i)||jsonb_build_object('sellable_qty',public.zp_sellable_qty(i.id),'channels',jsonb_build_object('table',jsonb_build_object('price_xaf',public.zp_current_price(i.id,'table'),'qty',public.zp_sellable_channel_qty(i.id,'table'),'groups',public.zp_formula_groups_view(i.id,'table')),'counter',jsonb_build_object('price_xaf',public.zp_current_price(i.id,'counter'),'qty',public.zp_sellable_channel_qty(i.id,'counter'),'groups',public.zp_formula_groups_view(i.id,'counter')),'takeaway',jsonb_build_object('price_xaf',public.zp_current_price(i.id,'takeaway'),'qty',public.zp_sellable_channel_qty(i.id,'takeaway'),'groups',public.zp_formula_groups_view(i.id,'takeaway')))) order by i.name),'[]'::jsonb) into items from public.zp_menu_items i where i.site_id=p_site and i.org_id=m.org_id;
 select coalesce(jsonb_agg(x.data),'[]'::jsonb) into orders from (select jsonb_build_object('id',o.id,'number',o.service_number,'table_session_id',o.table_session_id,'initial_promised_at',o.initial_promised_at,'guest_served_at',o.guest_served_at,'priority',o.priority,'called_at',o.called_at,'eta_saturated',o.eta_saturated,'channel',o.channel,'status',o.status,'total_xaf',o.total_xaf,'paid',exists(select 1 from public.zp_cash_receipts r where r.order_id=o.id),'promised_at',o.promised_at,'served_at',o.served_at,'created_at',o.created_at,'commercial_lines',o.commercial_lines,'lines',(select jsonb_agg(jsonb_build_object('item_id',l.item_id,'name',i.name,'qty',l.qty,'post',l.post,'state',l.state,'line_total_xaf',l.line_total_xaf,'instructions',l.instructions)) from public.zp_order_lines l join public.zp_menu_items i on i.id=l.item_id where l.order_id=o.id)) data from public.zp_orders o where o.site_id=p_site and o.org_id=m.org_id order by case when o.status in ('received','preparing','ready') then 0 else 1 end,o.priority desc,case when o.status in ('received','preparing','ready') then o.created_at end, o.created_at desc limit 100) x;
 select coalesce(jsonb_agg(jsonb_build_object('id',t.id,'label',t.label,'kind',t.kind,'session_id',(select id from public.zp_table_sessions s where s.table_id=t.id and s.closed_at is null))),'[]'::jsonb) into tables from public.zp_tables t where t.site_id=p_site and t.org_id=m.org_id;
 return jsonb_build_object('mode',mode,'items',items,'orders',orders,'tables',tables,'cash_session',(select jsonb_build_object('id',c.id,'opening_xaf',c.opening_xaf,'opened_at',c.opened_at) from public.zp_cash_sessions c where c.org_id=m.org_id and c.site_id=p_site and c.closed_at is null),'plan',public.zp_paid_plan(m.org_id),'server_now',now());end $$;

create or replace function public.zp_guest_order(p_guest_hash text,p_order uuid) returns jsonb language sql stable security invoker set search_path=pg_catalog,public as $$
 select jsonb_build_object('id',o.id,'number',o.service_number,'channel',o.channel,'called_at',o.called_at,'eta_saturated',o.eta_saturated,'initial_promised_at',o.initial_promised_at,'commercial_lines',o.commercial_lines,'paid',exists(select 1 from public.zp_cash_receipts r where r.order_id=o.id),'lines',(select jsonb_agg(jsonb_build_object('item_id',l.item_id,'name',i.name,'qty',l.qty,'unit_xaf',l.unit_xaf,'line_total_xaf',l.line_total_xaf,'state',l.state,'post',l.post)) from public.zp_order_lines l join public.zp_menu_items i on i.id=l.item_id where l.order_id=o.id),'status',o.status,'total_xaf',o.total_xaf,'created_at',o.created_at,'promised_at',o.promised_at,'served_at',o.served_at,'guest_served_at',o.guest_served_at,'server_now',now(),'service_delta_seconds',case when o.guest_served_at is not null and o.promised_at is not null then extract(epoch from o.guest_served_at-o.promised_at)::bigint else null end) from public.zp_orders o join public.zp_guest_sessions g on g.id=o.guest_id join public.zp_table_sessions ts on ts.id=g.table_session_id join public.zp_sites si on si.id=o.site_id join public.zp_organizations org on org.id=o.org_id where o.id=p_order and g.token_hash=p_guest_hash and g.expires_at>now() and ts.closed_at is null and si.active and org.active and public.zp_operational_plan(o.org_id) is not null
$$;
create or replace function public.zp_station_snapshot(p_access text,p_site uuid) returns jsonb language plpgsql stable security invoker set search_path=pg_catalog,public as $$
declare m public.zp_members;begin m:=public.zp_business_actor(p_access,p_site);
 return jsonb_build_object('server_now',now(),'posts',coalesce((select jsonb_agg(post) from public.zp_station_grants where member_id=m.id and site_id=p_site),'[]'::jsonb),'lines',coalesce((select jsonb_agg(jsonb_build_object('order_id',o.id,'number',o.service_number,'item_id',l.item_id,'name',i.name,'qty',l.qty,'post',l.post,'state',l.state,'priority',o.priority,'instructions',l.instructions,'guest_served_at',o.guest_served_at,'promised_at',o.promised_at) order by o.priority desc,o.created_at) from public.zp_order_lines l join public.zp_orders o on o.id=l.order_id join public.zp_menu_items i on i.id=l.item_id where l.org_id=m.org_id and l.site_id=p_site and o.status not in ('served','cancelled') and (m.role_code in ('promoteur','manager') or exists(select 1 from public.zp_station_grants g where g.member_id=m.id and g.site_id=p_site and g.post=l.post))),'[]'::jsonb),'items',coalesce((select jsonb_agg(jsonb_build_object('id',i.id,'name',i.name,'post',i.post,'active',i.active,'available_qty',i.available_qty,'sale_limit',i.sale_limit,'kind',i.kind)) from public.zp_menu_items i where i.org_id=m.org_id and i.site_id=p_site and (m.role_code in ('promoteur','manager') or exists(select 1 from public.zp_station_grants g where g.member_id=m.id and g.site_id=p_site and g.post=i.post))),'[]'::jsonb));end $$;

do $$ declare t text;f record;begin
 foreach t in array array['zp_station_capacity','zp_station_capacity_events'] loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from public,anon,authenticated',t);execute format('grant select,insert,update,delete on public.%I to service_role',t);end loop;
 for f in select p.oid::regprocedure sig from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('zp_capacity_set','zp_capacity_snapshot','zp_order_initial_eta','zp_delay_explain','zp_order_priority','zp_call_number','zp_business_snapshot','zp_guest_order','zp_station_snapshot') loop execute format('revoke all on function %s from public,anon,authenticated',f.sig);execute format('grant execute on function %s to service_role',f.sig);end loop;
end $$;
commit;
